# First, let me load all grids so far and check what we have
import os, re, json

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    import glob
    # Find the session file for this instance
    session_files = glob.glob(os.path.join(d, '../../sessions/*.jsonl'))
    if session_files:
        sf = session_files[-1]
        with open(sf) as f:
            text = f.read().replace('\\n', '\n')
        G = {}
        pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n')
        for m in pattern.finditer(text):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in text[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        return G
    return {}

G = load_grids()
print("Grids loaded:", sorted(G.keys()))

demo_input = G['Demo pair 1 input']
demo_output = G['Demo pair 1 output']

def transform_v1(grid):
    """Rule: 4 with >=3 adjacent 4s becomes 2"""
    R, C = len(grid), len(grid[0])
    adj = [[grid[r][c] for c in range(C)] for r in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 4:
                # Count 4-neighbors in 8 directions
                count = 0
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if grid[nr][nc] == 4:
                                count += 1
                if count >= 3:
                    adj[r][c] = 2
    return adj

def transform_v2(grid):
    """Rule: 4 becomes 2 if >= 3 of top/left/right/bottom are 4"""
    R, C = len(grid), len(grid[0])
    adj = [[grid[r][c] for c in range(C)] for r in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 4:
                count = 0
                # 4-way neighbors
                if r > 0 and grid[r-1][c] == 4:
                    count += 1
                if r < R-1 and grid[r+1][c] == 4:
                    count += 1
                if c > 0 and grid[r][c-1] == 4:
                    count += 1
                if c < C-1 and grid[r][c+1] == 4:
                    count += 1
                if count >= 3:
                    adj[r][c] = 2
    return adj

def transform_v3(grid):
    """Rule: 4 becomes 2 if bottom is 4"""
    R, C = len(grid), len(grid[0])
    adj = [[grid[r][c] for c in range(C)] for r in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 4 and r < R - 1:
                if grid[r+1][c] == 4:
                    adj[r][c] = 2
    return adj

