    result = []
    for r in range(R):
        row = []
        for c in range(C):
            if grid[r][c] == 4:
                # Has adjacent 4?
                has_adj = False
                # Check 8 directions
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if grid[nr][nc] == 4:
                                has_adj = True
                                break
                    if has_adj:
                        break

                if has_adj:
                    row.append(4)
                else:
                    row.append(2)
            else:
                row.append(grid[r][c])
        result.append(row)
    return result

